// People rows in, one morning message per active person out.
//
// The day's goals are read off their row, not invented here and not written by
// the model. Two numbers and one focus is the whole commitment: someone who has
// to read a paragraph before breakfast stops reading it by Wednesday.
//
// The date key is built here and nowhere else. The reply lane rebuilds the same
// key, which is how tonight's answer finds this morning's row instead of
// appending a second one.
const ZONE = 'Europe/Helsinki';

const today = $now.setZone(ZONE);
const dateKey = today.toFormat('yyyy-MM-dd');

const goals = [];

for (const item of $input.all()) {
  const person = item.json;

  const active = String(person.active ?? '').trim().toLowerCase();
  if (!['true', 'yes', '1', 'x'].includes(active)) continue;

  // Sheets hands phone numbers back as text or as a number, with or without a
  // +. WhatsApp always reports the sender as bare digits, so normalise to that.
  const phone = String(person.phone ?? '').replace(/\D/g, '');
  if (!phone) continue;

  const name = String(person.name ?? '').trim() || phone;
  const first = name.split(/\s+/)[0];

  const callsTarget = Number(person.calls_target) || 0;
  const hoursCap = Number(person.hours_cap) || 0;

  // Free text, straight off the sheet. The coach matches it against the Focus
  // column in the playbook library, so whoever owns the sheet decides what the
  // focuses are — nothing here knows or cares what the words mean.
  const focus = String(person.focus ?? '').trim();

  // Someone with no focus set still gets their numbers. The reminder is the
  // part that is optional, not the commitment.
  const reminder = focus ? `\n\nFocus: *${focus}*.` : '';

  goals.push({
    json: {
      key: `${dateKey}|${phone}`,
      date: dateKey,
      weekday: today.toFormat('ccc'),
      name,
      phone,
      focus,
      calls_target: callsTarget,
      calls: '',
      hours_cap: hoursCap,
      hours: '',
      status: 'goal_set',
      note: '',
      raw_reply: '',
      logged_at: today.toISO(),
      message:
        `Morning ${first}. Today: *${callsTarget} calls*, and stay under `
        + `*${hoursCap}h* on them.${reminder}\n\nTell me how it went tonight — `
        + `"${callsTarget}/${hoursCap}" is enough, or just talk to me.`,
    },
  });
}

return goals;

// One output item per inbound text message from someone the coach is monitoring.
//
// Deterministic parse first, agent second. "6", "6/3" and "none" cover the
// evening check-in and cost nothing; everything else — a question, an excuse,
// a paragraph about a deal that went sideways — is handed to the agent. Putting
// the cheap path first is what keeps the log trustworthy: the number that ends
// up in the spreadsheet on a normal evening was read by a regex, not chosen by
// a model.
const ZONE = 'Europe/Helsinki';

// A reply typed at 00:30 is about the day that just ended, not the new one.
const DAY_ROLLOVER_HOUR = 4;

const ALL_WORDS = ['all', 'all of them', 'yes', 'yep', 'yup', 'done', 'all done', 'kaikki', 'joo', 'kyllä'];
const NONE_WORDS = ['none', 'no', 'nope', 'zero', '0', 'ei', 'en yhtään'];

// Nobody works more than this in a day, so a bigger number is a typo or a
// different unit and belongs to the agent to sort out.
const MAX_HOURS = 18;
const MAX_CALLS = 100;

// A bare count, or a count and the hours it took: "6", "6/3", "6 / 3", "6-3".
// Only trusted when the message is essentially just that, so "tomorrow I'll do
// 8" is never logged as eight calls today.
function parse(text, callsTarget) {
  const clean = text.trim().toLowerCase();

  if (ALL_WORDS.includes(clean)) return { calls: callsTarget, hours: null, how: 'all' };
  if (NONE_WORDS.includes(clean)) return { calls: 0, hours: null, how: 'none' };

  if (clean.length > 12) return { calls: null, hours: null, how: 'unparsed' };

  const pair = clean.match(/^(\d{1,3})\s*[/\-,]\s*(\d{1,2}(?:[.,]\d)?)\s*h?$/);
  if (pair) {
    const calls = Number(pair[1]);
    const hours = Number(pair[2].replace(',', '.'));
    if (calls <= MAX_CALLS && hours <= MAX_HOURS) return { calls, hours, how: 'calls+hours' };
    return { calls: null, hours: null, how: 'unparsed' };
  }

  const single = clean.match(/(?<!\d)(\d{1,3})(?!\d)/);
  if (single) {
    const calls = Number(single[1]);
    if (calls <= MAX_CALLS) return { calls, hours: null, how: 'calls' };
  }

  return { calls: null, hours: null, how: 'unparsed' };
}

// The people list arrives on this node's input; the messages come from the
// trigger.
const people = new Map();
for (const item of $input.all()) {
  const phone = String(item.json.phone ?? '').replace(/\D/g, '');
  if (phone) people.set(phone, item.json);
}

const out = [];

for (const event of $('WhatsApp Trigger').all()) {
  for (const message of event.json.messages ?? []) {
    if (message.type !== 'text') continue;

    const phone = String(message.from ?? '').replace(/\D/g, '');
    const person = people.get(phone);

    // Someone not on the list messaged the business number. Not ours to log.
    if (!person) continue;

    const text = String(message.text?.body ?? '').trim();
    const callsTarget = Number(person.calls_target) || 0;
    const hoursCap = Number(person.hours_cap) || 0;

    const stamp = Number(message.timestamp);
    const receivedAt = Number.isFinite(stamp) && stamp > 0
      ? DateTime.fromSeconds(stamp).setZone(ZONE)
      : $now.setZone(ZONE);

    const forDay = receivedAt.hour < DAY_ROLLOVER_HOUR
      ? receivedAt.minus({ days: 1 })
      : receivedAt;

    const dateKey = forDay.toFormat('yyyy-MM-dd');
    const { calls, hours, how } = parse(text, callsTarget);

    out.push({
      json: {
        key: `${dateKey}|${phone}`,
        date: dateKey,
        weekday: forDay.toFormat('ccc'),
        name: String(person.name ?? '').trim() || phone,
        phone,
        focus: String(person.focus ?? '').trim(),
        calls_target: callsTarget,
        calls: calls === null ? '' : calls,
        hours_cap: hoursCap,
        hours: hours === null ? '' : hours,
        status: calls === null ? 'unparsed' : 'logged',
        note: how,
        raw_reply: text,
        logged_at: receivedAt.toISO(),
        // Routing only. True means the regex read a number and the agent is
        // not needed; false hands the whole message over.
        parsed: calls !== null,
        message_id: message.id ?? '',
      },
    });
  }
}

return out;

